export const bill_energy=calculator((i,d)=>{const t=tariffOf(d);const units=nonneg(i,'units');const sanctioned_kw=flatSanctioned(i,d);const category=categoryOf(i);return{units,sanctioned_kw,category,...energyCharge(t,units,category,sanctioned_kw)};});export const bill_tou=calculator((i,d)=>{const t=tariffOf(d).tou;const peak_units=nonneg(i,'peak_units');const offpeak_units=nonneg(i,'offpeak_units');const sanctioned_kw=pos(i,'sanctioned_kw');const mdi_kw=nonneg(i,'mdi_kw',0);if(!(t.fixed_min_fraction>0))throw new CalcError('tariff_data_missing','tariff');const billable_kw=Math.max(t.fixed_min_fraction*sanctioned_kw,mdi_kw);const energy_rs=peak_units*t.peak+offpeak_units*t.offpeak;return{peak_units,offpeak_units,units:peak_units+offpeak_units,sanctioned_kw,mdi_kw,billable_kw,energy_rs,fixed_rs:t.fixed_per_kw*billable_kw};});
export const bill_total=calculator((i,d)=>{const base=bill_energy.raw(i,d);const a=tariffOf(d).addons_secondary||{};const life=base.category==='lifeline';const fc=nonneg(i,'fc_surcharge_per_unit',life?0:a.fc_surcharge_per_unit?.value??0);const period=has(i,'period')?String(i.period):null;const qtaTable=a.qta_per_unit||{};const qtaDefault=period&&/^\d{4}-\d{2}\.\.\d{4}-\d{2}$/.test(period)&&Object.hasOwn(qtaTable,period)?qtaTable[period]:undefined;if(period&&typeof qtaDefault !=='number')throw new CalcError('period_unknown','period');const qta=num(i,'qta_per_unit',{def:qtaDefault??0});const fpa=num(i,'fpa_per_unit',{def:a.fpa_per_unit?.value??0});const gst_pct=num(i,'gst_pct',{def:life?0:a.gst_pct?.value??0,min:0,max:100});const fc_rs=fc*base.units;const qta_rs=base.category==='lifeline'?0:qta*base.units;const fpa_exempt=base.category !=='unprotected';const fpa_rs=fpa_exempt?0:fpa*base.units;const subtotal_rs=Math.max(0,base.energy_rs+base.fixed_rs+fc_rs+qta_rs+fpa_rs);const gst_rs=(subtotal_rs*gst_pct)/100;return{...base,fc_surcharge_per_unit:fc,qta_per_unit:qta,fpa_per_unit:fpa,fpa_exempt,fc_rs,qta_rs,fpa_rs,subtotal_rs,gst_pct,gst_rs,total_rs:subtotal_rs+gst_rs};},{allowNegative:['qta_rs','fpa_rs','qta_per_unit','fpa_per_unit']});export const protected_check=calculator((i,d)=>{const h=i.history;const months=dflt(d,'protected_months');const limit=dflt(d,'protected_max_units');if(!Array.isArray(h)||h.length !==months)throw new CalcError(`history_needs_${months}_months`,'history');h.forEach((u,idx)=>num({history:u},'history',{min:0,code:`history_${idx+1}_invalid`}));const sanctioned_kw=pos(i,'sanctioned_kw',dflt(d,'default_sanctioned_kw'));const tou=bool(i.tou)||sanctioned_kw>=dflt(d,'tou_threshold_kw');const max_month=Math.max(...h);const reasons=[];if(max_month>limit)reasons.push('month_over_200');if(tou)reasons.push('tou_or_5kw');return{protected:reasons.length===0,max_month,reasons_count:reasons.length,reasons};});
export const net_billing=calculator((i,d)=>{const t=tariffOf(d);const import_units=nonneg(i,'import_units');const export_units=nonneg(i,'export_units');const buyback_rs=nonneg(i,'buyback_rs',t.net_billing?.buyback_rs_per_unit_default);const sanctioned_kw=flatSanctioned(i,d);const imp=energyCharge(t,import_units,categoryOf(i),sanctioned_kw);const export_credit_rs=export_units*buyback_rs;const diff=imp.energy_rs-export_credit_rs;const net_metering_units=Math.max(0,import_units-export_units);const old=energyCharge(t,net_metering_units,categoryOf(i),sanctioned_kw);const net_energy_rs=Math.max(0,diff);return{import_units,export_units,buyback_rs,import_rate:imp.rate,import_energy_rs:imp.energy_rs,export_credit_rs,net_energy_rs,carry_forward_rs:Math.max(0,-diff),net_metering_units,net_metering_rate:old.rate,net_metering_rs:old.energy_rs,net_metering_carry_units:Math.max(0,export_units-import_units),extra_vs_net_metering_rs:Math.max(0,net_energy_rs-old.energy_rs),};});
export const bill_audit=calculator((i,d)=>{const t=tariffOf(d);const units=nonneg(i,'units');const days=pos(i,'days');const cycle=dflt(d,'days_per_month');const units_30=(units*cycle)/days;const bands=t.unprotected;const limit=dflt(d,'protected_max_units');const slab_jump=bandIndex(bands,units_30)<bandIndex(bands,units);const out={units,days,units_30,long_cycle:days>dflt(d,'max_normal_cycle_days'),slab_jump,protection_at_risk:units>limit&&units_30<=limit,};if(has(i,'sanctioned_kw')){const kw=pos(i,'sanctioned_kw');const actual=energyCharge(t,units,'unprotected',kw);const fair=energyCharge(t,units_30,'unprotected',kw);const fair_rs=units*fair.rate+fair.fixed_rs;out.billed_rs=actual.energy_rs+actual.fixed_rs;out.fair_rs=fair_rs;out.extra_rs=Math.max(0,out.billed_rs-fair_rs);}
if(has(i,'prev_year_units')){const prev=nonneg(i,'prev_year_units');out.spike=prev>0&&units>prev*(1+dflt(d,'spike_threshold'));}
return out;});
